<script lang="ts">
 import ServerManagementRow from './ServerManagementRow.svelte';
 import AgentUpdates from './AgentUpdates.svelte';import XrayManager from './XrayManager.svelte';let xrayServer=$state<Row|null>(null);let xrayDeepLink=$state('');
 $effect(()=>{if(collection!=='servers'||demo.user?.role!=='admin')return;const key=page.url.search;if(key===xrayDeepLink)return;const inbound=(demo.data.inbounds??[]).find(row=>row.id===page.url.searchParams.get('inbound'));const id=page.url.searchParams.get('xray')||inbound?.serverId;if(!id)return;const target=(demo.data.servers??[]).find(row=>row.id===id);if(target){xrayDeepLink=key;xrayServer=target;}});
 import MerchantBilling from './MerchantBilling.svelte';
 import RegistrationInvites from './RegistrationInvites.svelte';
 import {routingURL} from '../routing';
 import {onMount,onDestroy} from 'svelte';import {page} from '$app/state';import Icon from './Icon.svelte';import Modal from './Modal.svelte';import Badge from './Badge.svelte';import AppSelect from './Select.svelte';import {modules,type Field} from '../modules';import {demo,saveRow,removeRow,download,money,toast,copy,getRow,runAction,api,errorMessage,refreshState} from '../store.svelte';import type {Row} from '../data';import {formatUsagePercent,formatNumber,formatDisplayValue} from '../format';
 import CountryBadge from './CountryBadge.svelte';import ServerManagementCard from './ServerManagementCard.svelte';import FederationAgent from './FederationAgent.svelte';
 import BehaviorEditor from './BehaviorEditor.svelte';import NodeLimitEditor from './NodeLimitEditor.svelte';
 import ExpandableValue from './ExpandableValue.svelte';
 import LogDateDelete from './LogDateDelete.svelte';
