 const detailLabels:Record<string,string>={core:'核心版本',agentVersion:'Agent 版本',capabilities:'支持能力',observation:'运行详情',cpu:'CPU 使用率',memory:'内存使用率',createdAt:'创建时间',updatedAt:'更新时间',lastSeen:'最后在线',deploymentTag:'部署标记',managementMode:'接入模式',upload:'上传速率',download:'下载速率',latencyStatus:'测速状态',latencyError:'测速错误',latencyKind:'测速方式',testedAt:'测速时间'};
 import ServerOnboarding from './ServerOnboarding.svelte';import AgentInstall from './AgentInstall.svelte';let onboardingOpen=$state(false);
 import {withManagedFields,managedInboundError,prepareManagedInbound} from '../managed-protocols';
