 import {withRealityFields,realityLabels} from '../reality';
 let taskOutput=$state<any>(null),taskOutputError=$state(''),lastTask=$state(''),certificateOpen=$state(false),certificatePEM=$state(''),certificateKey=$state('');let keyBusy=$state(false),saving=$state(false),loading=$state(false),enrollment=$state<Record<string,any>|null>(null),acting=$state(false),coreConfig=$state(''),coreError=$state(''),configTask=$state('');let deleteError=$state('');let disposed=false;onDestroy(()=>disposed=true);const actionNames:Record<string,string>={servers:'server.config.apply',inbounds:'inbound.config.apply',outbounds:'outbound.config.apply',nodes:'node.health.check',sources:'source.sync',members:'member.credentials.sync',certificates:'certificate.renew',tasks:'task.retry',notifications:'notification.test'};
 let {collection}=$props<{collection:string}>();let sharingOpen=$state(false),hideIP=$state(false);function toggleIP(){hideIP=!hideIP;try{localStorage.setItem('aswired-hide-server-ip',String(hideIP));}catch{}}let serverView=$state<'cards'|'list'>('cards');function setServerView(view:'cards'|'list'){serverView=view;try{localStorage.setItem('aswired-server-view',view);}catch{}}const config=$derived(modules[collection]);let isNew=$state(false);let search=$state(''),filter=$state('全部状态'),edit=$state(false),detail=$state(false),deleting=$state(false),form=$state<Row>({id:''}),selected=$state<Row|null>(null),error=$state(''),offset=$state(0),detailTab=$state('概况');
 const canViewDetails=$derived(canViewResourceDetails(demo.user?.role,collection));const rows=$derived(demo.data[collection]??[]);const editableFields=$derived(config.fields.filter(field=>!field.adminOnly||demo.user?.role==='admin'));const canCreate=$derived(canCreateResource(demo.user?.role,collection,config.readonly));const canManage=(row:Row)=>canManageResource(demo.user?.role,collection,row,config.readonly);const canDelete=(row:Row)=>canDeleteResource(demo.user?.role,collection,row,config.readonly);const logCollection=$derived(['tasks','audit'].includes(collection));const canAct=(row:Row)=>collection==='nodes'?canTestNode(demo.user?.role,row):demo.user?.role==='admin'&&(collection!=='tasks'||taskView(row).canRetry);const filtered=$derived(rows.filter(r=>matchesSearch(r)&&(filter==='全部状态'||(r.status??r.result)===filter)));const statuses=$derived([...new Set(rows.map(r=>r.status??r.result).filter(Boolean))]);const visible=$derived(filtered.slice(offset,offset+10));
 const onlineCount=$derived(rows.filter(row=>['在线','告警'].includes(row.status)).length);const offlineCount=$derived(rows.filter(row=>row.status==='离线').length);const pendingCount=$derived(rows.length-onlineCount-offlineCount);const nodeTestIdentity=()=>demo.user?`${demo.user.id}:${demo.user.role}`:'';
 const nodeTests=createNodeLatencyTests({identity:nodeTestIdentity,canTest:id=>collection==='nodes'&&rows.some(row=>row.id===id&&canAct(row)),read:(id,signal)=>api('/api/actions',{method:'POST',body:JSON.stringify({action:'node.health.check',targetId:id,collection:'nodes'}),signal})});
 const testableNodes=$derived(collection==='nodes'?rows.filter(canAct):[]);
 $effect(()=>nodeTests.syncIdentity());
 onDestroy(()=>nodeTests.clear());
 let nodeResultsSynced=$state(false),nodeTestRun=0;
 async function testNodes(targets:Row[]){if(nodeTests.state.running)return;const run=++nodeTestRun;nodeResultsSynced=false;const identity=nodeTestIdentity();const result=await nodeTests.run(targets.map(row=>row.id));if(!result||disposed||run!==nodeTestRun||identity!==nodeTestIdentity())return;try{await refreshState(true);if(!disposed&&run===nodeTestRun&&identity===nodeTestIdentity()&&!nodeTests.state.running)nodeResultsSynced=true;}catch{if(!disposed&&run===nodeTestRun&&identity===nodeTestIdentity())toast('测速已结束，列表刷新失败，请稍后刷新');}}
 function nodeLatency(row:Row){const result=nodeResultsSynced?undefined:nodeTests.state.results[row.id];if(result?.status==='success')return formatNumber(result.latency);if(result?.status==='failed')return '失败';if(result?.status==='running')return '测速中…';if(result?.status==='queued')return '等待中';if(result?.status==='cancelled')return '已取消';return row.latencyStatus==='failed'?'失败':formatNumber(row.latency);}
 function nodeLatencyHint(row:Row){return (!nodeResultsSynced&&nodeTests.state.results[row.id]?.error)||row.latencyError||'主控到节点的 TCP 连接延迟';}
 function identityBadge(row:Row){return String(row.name??'').slice(0,1);}
 const formFields=$derived(editableFields.filter(field=>{if(collection==='inbounds'&&['protocol','transport','flow'].includes(field.key))return false;if(collection==='members'&&field.key==='behaviorLimits')return false;if(collection==='servers'&&['agentPort','agentUrl'].includes(field.key)&&!['自动','HTTP','auto','http'].includes(form.connection))return false;if(collection!=='certificates')return true;const keys=['credential','accessKeyId','accessKeySecret','secretId','secretKey'];if(!keys.includes(field.key))return true;if(form.challenge==='HTTP-01')return false;return form.provider==='alidns'?['accessKeyId','accessKeySecret'].includes(field.key):form.provider==='dnspodcn'?['secretId','secretKey'].includes(field.key):field.key==='credential';}).map(field=>collection==='nodes'&&field.key==='uri'?{...field,required:isNew}:field));
 $effect(()=>{if(detail&&selected&&collection==='tasks'){const current=rows.find(row=>row.id===selected!.id);if(current)selected=current;}});
 $effect(()=>{if(collection!=='nodes')return;if(demo.user?.role!=='admin'){edit=false;deleting=false;detail=false;selected=null;return;}if(detail&&selected){const current=rows.find(row=>row.id===selected!.id);if(current)selected=current;else{detail=false;selected=null;}}});
 function matchesSearch(row:Row){const values=Object.entries(row).filter(([key])=>!['privateKey','realitySettings'].includes(key)).map(([,value])=>value);if(collection==='tasks')values.push(taskView(row).targetName,taskView(row).address);return values.join(' ').toLowerCase().includes(search.toLowerCase());}
 function taskView(row:Row){return taskStatus(row,demo.data.servers??[],demo.data.endpoints??[]);}
 function fieldOptions(field:Field){return field.type==='endpoints'?[{value:'',label:'主控直接抓取'},...(demo.data.endpoints??[]).map(row=>({value:row.id,label:row.name}))]:field.options??demo.data[field.type!]?.map(r=>r.name)??[];}
 function changeOutboundType(value:string){form.protocol=value;for(const key of ['settings','streamSettings'])form[key]=value==='VLESS'?JSON.stringify(modules.outbounds.fields.find(field=>field.key===key)?.value??{},null,2):'{}';}
 async function create(row?:Row){if(loading||!canCreate||(row&&!canManage(row)))return;if(collection==='servers'&&!row){onboardingOpen=true;return;}const identity=nodeTestIdentity();loading=true;try{if(row)row=await getRow(collection,row.id);if(disposed||identity!==nodeTestIdentity()||!canCreate||(row&&!canManage(row)))return;isNew=!row;form=row?{...row}:{id:crypto.randomUUID(),...Object.fromEntries(editableFields.map(f=>[f.key,f.value??''])),status:collection==='servers'?'待接入':collection==='billing'?'待支付':'启用',used:0,cpu:null,memory:null,clients:0,nodes:0,code:'NW',version:0};for(const f of editableFields)if(['servers','plans','members','carpools'].includes(f.type??'')&&!form[f.key])form[f.key]=fieldOptions(f)[0]??'';for(const field of editableFields.filter(field=>['json','jsonarray'].includes(field.type??'')))form[field.key]=form[field.key]?JSON.stringify(form[field.key],null,2):'';if(collection==='inbounds')form=withManagedFields(withRealityFields(form));error='';edit=true;}catch(cause){toast(errorMessage(cause));}finally{loading=false;}}
 async function changeServerConnection(row:Row,connection:string){
  try{const current=await getRow('servers',row.id);await saveRow('servers',{...current,connection});toast(row.connectionSwitchSupported===false?'已保存；请升级 Agent 后应用连接模式':'已保存，等待 Agent 应用连接模式');}catch(cause){toast(errorMessage(cause));}
 }
 async function submit(){
  if(saving||keyBusy||!canCreate)return;const current=rows.find(row=>row.id===form.id);if(current&&!canManage(current))return;
  error='';
  for(const field of formFields){
   if(field.required&&!String(form[field.key]??'').trim()){error=`请填写${field.label}`;return;}
   if(field.type==='number'&&!(field.optional&&(form[field.key]==null||form[field.key]===''))){const value=Number(form[field.key]);if(!Number.isFinite(value)||value<(field.min??0)||(field.max!=null&&value>field.max)){error=`${field.label}须为 ${field.min??0} ${field.max!=null?'至 '+field.max:'以上'}的数字`;return;}}
  }
  if(collection==='inbounds'&&form.status!=='停用'){error=managedInboundError(form);if(error)return;}
  if(collection==='inbounds'&&(!Number.isInteger(form.port)||form.port<1||form.port>65535)){error='端口须为 1–65535 的整数';return;}
  if(collection==='inbounds'&&rows.some(r=>r.id!==form.id&&r.server===form.server&&r.port===form.port)){error='同一服务器的端口已被使用';return;}
  if(collection==='nodes'&&(isNew||form.status!=='停用')){if(String(form.uri??'').trim())error=nodeURIError(String(form.uri));else if(!isSupportedNode(form))error='请粘贴支持的节点链接，或停用此记录';if(error)return;}
  if(collection==='members'&&!rows.some(row=>row.id===form.id)&&!String(form.password??'')){error='创建账户需要设置至少 12 字节的密码';return;}
  const original=form;const draft:Row={...form,...(collection==='servers'?{xray_mode:'embedded',connection:form.connection||'自动'}:{})};const snapshot=JSON.stringify(draft);for(const field of formFields.filter(field=>['json','jsonarray'].includes(field.type??''))){if(!String(draft[field.key]??'').trim()){if(field.key==='behaviorLimits')draft[field.key]=null;else if(field.type==='jsonarray')draft[field.key]=[];else delete draft[field.key];continue;}try{draft[field.key]=JSON.parse(draft[field.key]);if(!draft[field.key]||Array.isArray(draft[field.key])!==(field.type==='jsonarray')||typeof draft[field.key]!=='object')throw new Error();}catch{error=`${field.label}须为有效 JSON ${field.type==='jsonarray'?'数组':'对象'}`;return;}}
  if(collection==='members'){try{draft.behaviorLimits=String(form.behaviorLimits??'').trim()?JSON.parse(form.behaviorLimits):null;}catch{error='行为限速 JSON 无效';return;}}
  saving=true;
  for(const field of formFields.filter(field=>field.type==='number'&&field.optional))draft[field.key]=draft[field.key]==null||draft[field.key]===''?null:Number(draft[field.key]);
  try{
   let saved:Row;
   if(collection==='inbounds'){
    const prepared=await prepareManagedInbound(draft);
    if(!edit||form!==original)return;
    if(JSON.stringify(form)!==snapshot){error='配置已变更，请重新保存';return;}
    saved=await saveRow(collection,prepared);
   }else saved=await saveRow(collection,draft);
   if(disposed||form!==original)return;
   edit=false;
   toast(demo.user?.role==='admin'?'配置已保存；节点执行状态请查看任务':'配置已保存');
  }catch(cause){if(edit&&form===original)error=cause instanceof Error?cause.message:'保存失败，请重试';}
  finally{saving=false;}
 }

 async function show(row:Row,tab?:string){if(!canViewDetails)return;taskOutput=null;taskOutputError='';selected=row;enrollment=null;coreConfig='';coreError='';configTask='';detailTab=tab??(collection==='tasks'?'执行结果':'概况');detail=true;if(collection==='tasks')await readTaskOutput();else if(detailTab==='接入指引')await loadEnrollment();}
 async function readTaskOutput(){if(!selected||loading)return;const id=selected.id;loading=true;taskOutputError='';try{const task=await getRow('tasks',id);if(!disposed&&detail&&selected?.id===id)taskOutput=task.result;}catch(cause){if(detail)taskOutputError=errorMessage(cause);}finally{loading=false;}}
 $effect(()=>{if(!detail){taskOutput=null;taskOutputError='';}});
 async function loadEnrollment(){if(!selected)return;const id=selected.id;acting=true;try{const result=await api(`/api/servers/${encodeURIComponent(id)}/enrollment`);if(!disposed&&detail&&selected?.id===id)enrollment=result;}catch(cause){if(!disposed&&detail&&selected?.id===id)toast(errorMessage(cause));}finally{acting=false;}}
 async function action(row:Row){if(acting||!canAct(row))return;acting=true;try{const result=await runAction(actionNames[collection]??config.action??'unsupported',row.id,collection);lastTask=demo.user?.role==='admin'?result.task?.id??'':'';toast(result.task?demo.user?.role==='admin'?'请求已受理，请查看执行状态':'请求已提交，可稍后查看资源更新':result.message??'操作完成');}catch(cause){toast(errorMessage(cause));}finally{acting=false;}}
 function requestDelete(row:Row){if(saving||!canDelete(row))return;selected=row;deleteError='';detail=false;deleting=true;}
 async function deleteSelected(){
  if(!selected||saving||!canDelete(selected))return;
  const target=selected;const targetCollection=collection;saving=true;deleteError='';
  try{await removeRow(targetCollection,target.id);if(disposed)return;if(selected?.id===target.id){deleting=false;detail=false;selected=null;}offset=Math.min(offset,Math.max(0,Math.ceil(filtered.length/10)-1)*10);toast(targetCollection==='servers'?'服务器已移出主控':'已删除记录');}
  catch(cause){if(!disposed){if(deleting&&selected?.id===target.id)deleteError=errorMessage(cause);else toast(errorMessage(cause));}}
  finally{saving=false;}
 }
 async function readCoreConfig(){if(!selected||acting)return;acting=true;coreError='';const serverId=selected.id;try{const result=await runAction('core.config.get',serverId,'servers');const id=result.task?.id;if(!id)throw new Error('主控未返回配置读取任务');configTask=id;for(let attempt=0;attempt<60&&!disposed&&detail&&selected?.id===serverId;attempt++){const task=await getRow('tasks',id);if(['成功','success','succeeded'].includes(task.status)){const config=task.result?.config??task.result?.data?.config??task.data?.config;if(!config)throw new Error('任务未返回核心配置');coreConfig=JSON.stringify(config,null,2);configTask='';return;}if(['失败','不支持','结果未明','failed','unsupported','unknown'].includes(task.status))throw new Error(task.error??'配置读取失败');await new Promise(resolve=>setTimeout(resolve,1000));}if(!disposed&&detail)coreError='仍在等待 Agent，可在任务页面查看结果';}catch(cause){coreError=errorMessage(cause);}finally{acting=false;}}
 async function applyCoreConfig(){if(!selected||acting)return;coreError='';let config;try{config=JSON.parse(coreConfig);if(!config||Array.isArray(config)||typeof config!=='object')throw new Error();}catch{coreError='请填写有效的完整 Xray JSON 配置';return;}acting=true;try{const result=await runAction('core.config.apply',selected.id,'servers',{config});configTask=result.task?.id??'';toast('配置已提交，Agent 检查通过后会应用并重启核心；请查看任务结果');}catch(cause){coreError=errorMessage(cause);}finally{acting=false;}}
 async function certificateAction(action:string){if(!selected||acting)return;acting=true;try{const result=await runAction(action,selected.id,'certificates',action==='certificate.upload'?{certificate:certificatePEM,privateKey:certificateKey}:{});toast(result.message??'操作已完成');if(action==='certificate.upload'){certificateOpen=false;certificatePEM='';certificateKey='';}}catch(cause){toast(errorMessage(cause));}finally{acting=false;}}
 function csv(){const cols=config.columns;download(`${collection}.csv`,'\uFEFF'+[cols.map(c=>c[1]).join(','),...filtered.map(r=>cols.map(([k])=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n'),'text/csv');toast('已导出当前筛选结果');}
 onMount(()=>{try{hideIP=localStorage.getItem('aswired-hide-server-ip')==='true';if(localStorage.getItem('aswired-server-view')==='list')serverView='list';}catch{}const editID=page.url.searchParams.get('edit');const editRow=rows.find(r=>r.id===editID);if(editRow)void create(editRow);else if(page.url.searchParams.has('new'))create();const id=page.url.searchParams.get('detail');const row=rows.find(r=>r.id===id);if(row)show(row);});
</script>
{#snippet rowIdentity(row:Row,key:string)}{#if collection==='servers'||collection==='nodes'}<CountryBadge region={row.region} code={row.code} observedRegion={row.observation?.region}/>{:else}<span class="region-avatar">{identityBadge(row)}</span>{/if}<span><strong>{row[key]}</strong>{#if collection==='servers'}<small>{row.provider}</small>{:else if demo.user?.role==='user'&&collection==='nodes'&&!canManage(row)}<small>订阅节点 · 只读</small>{/if}</span>{/snippet}
<div class="page-head"><div><div class="eyebrow">工作区 / {config.title}</div><h1>{config.title}</h1><p>{collection==='nodes'&&demo.user?.role==='user'?'查看当前有效订阅中的节点与连接延迟。':config.sub}</p></div><div class="actions">{#if logCollection&&demo.user?.role==='admin'}{#key collection}<LogDateDelete {collection} onDeleted={()=>{offset=0;detail=false;selected=null;}}/>{/key}{/if}{#if collection==='nodes'}<button class="button" disabled={nodeTests.state.running||acting||!testableNodes.length} title={`测试全部 ${testableNodes.length} 个可测速节点，包含所有分页`} onclick={()=>testNodes(testableNodes)}><Icon name="zap"/>{nodeTests.state.running?`测速中 ${nodeTests.state.completed}/${nodeTests.state.total}`:'一键测速全部'}</button>{/if}<button class="button" onclick={csv}><Icon name="download"/>导出</button>{#if canCreate&&collection!=='servers'}<button class="button primary" onclick={()=>create()}><Icon name="plus"/>新增{collection==='servers'?'服务器':'记录'}</button>{/if}</div></div>
{#if collection==='members'&&demo.user?.role==='admin'}<RegistrationInvites/>{/if}
{#if lastTask&&demo.user?.role==='admin'}<div class="status-banner">请求已受理。<a href={`/tasks?detail=${encodeURIComponent(lastTask)}`}>查看任务执行结果</a></div>{/if}
{#if collection==='nodes'&&nodeTests.state.total}<div class="node-test-progress" role="status" aria-live="polite"><span>{nodeTests.state.running?(nodeTests.state.stopping?'正在停止测速':'正在测速'):'测速已结束'} · {nodeTests.state.completed} / {nodeTests.state.total} · 成功 {nodeTests.state.succeeded} · 失败 {nodeTests.state.failed}{#if !nodeTests.state.running&&nodeTests.state.completed<nodeTests.state.total} · 未完成 {nodeTests.state.total-nodeTests.state.completed}{/if}</span>{#if nodeTests.state.running}<button class="button small" disabled={nodeTests.state.stopping} onclick={nodeTests.stop}>停止测速</button>{/if}</div>{/if}
{#if collection==='billing'}<div class="stat-grid"><div class="card stat-card"><span class="muted">本期应收</span><div class="stat-number">{money(rows.reduce((s,r)=>s+r.amount,0))}</div></div><div class="card stat-card"><span class="muted">已核销</span><div class="stat-number">{money(rows.filter(r=>r.status==='已核销').reduce((s,r)=>s+r.amount,0))}</div></div><div class="card stat-card"><span class="muted">待核销</span><div class="stat-number">{rows.filter(r=>r.status==='待核销').length}<small> 笔</small></div></div><a href="/carpools" class="card stat-card"><span class="muted">车队分摊</span><div class="stat-number">费用试算 <Icon name="arrow"/></div></a></div>{/if}
{#if demo.user?.role==='user'&&collection==='nodes'}<p class="hint">仅显示你的有效订阅包含的节点，可查看列表和测速。节点由管理员维护。</p>{/if}
{#if logCollection}<p class="hint log-retention">{collection==='tasks'?'任务执行记录默认保留 7 天；待下发、执行中、结果未明或仍被使用的任务会继续保留。':'审计日志默认保留 7 天，超过期限自动清理。'}{demo.user?.role==='admin'?' 管理员可提前删除历史记录。':''}</p>{/if}
{#if collection==='servers'}
<div class="server-tools"><div class="actions">
 <div class="segmented view-switch" aria-label="服务器布局"><button class:active={serverView==='cards'} aria-pressed={serverView==='cards'} onclick={()=>setServerView('cards')}><Icon name="grid" size={14}/>卡片</button><button class:active={serverView==='list'} aria-pressed={serverView==='list'} onclick={()=>setServerView('list')}><Icon name="list" size={14}/>列表</button></div>
 <button class="button" aria-pressed={hideIP} onclick={toggleIP}><Icon name={hideIP?'lock':'eye'} size={14}/>{hideIP?'显示 IP':'隐藏 IP'}</button>
 {#if canCreate}<button class="button primary" onclick={()=>create()}><Icon name="plus" size={14}/>添加服务器</button>{/if}
 {#if demo.user?.role==='admin'}<button class="button" onclick={()=>sharingOpen=true}><Icon name="link" size={14}/>接入共享服务器</button><MerchantBilling/><AgentUpdates/>{/if}
</div><div class="server-counts" aria-label="服务器状态统计"><span><i class="online"></i>在线 <strong>{onlineCount}</strong></span><span><i></i>离线 <strong>{offlineCount}</strong></span>{#if pendingCount}<span>其他 <strong>{pendingCount}</strong></span>{/if}</div></div>
{/if}
<section class="card no-pad" class:server-collection={collection==='servers'}><div class="toolbar"><div class="search-input"><Icon name="search"/><input aria-label={`搜索${config.title}`} placeholder={`搜索${config.title}…`} bind:value={search} oninput={()=>offset=0}/></div><div class="actions"><AppSelect aria-label="按状态筛选" bind:value={filter} options={["全部状态",...statuses]} onchange={()=>offset=0}/><span class="muted">{filtered.length} 条记录</span></div></div><div class:server-view-body={collection==='servers'}>{#if collection==='servers'}<div class="server-card-grid" class:inactive-view={serverView!=='cards'} inert={serverView!=='cards'} aria-hidden={serverView!=='cards'}>{#each visible as row (row.id)}<ServerManagementCard server={row} onconnection={canManage(row)?mode=>changeServerConnection(row,mode):undefined} {hideIP} onview={canViewDetails?()=>show(row):undefined} onconfig={canManage(row)&&canViewDetails?()=>xrayServer=row:undefined} onagent={canManage(row)&&canViewDetails?()=>show(row,'接入指引'):undefined}>{#snippet actions()}{#if demo.user?.role==='admin'&&['servers','inbounds','nodes'].includes(collection)&&routingURL(collection,row)}<a class="icon-button" href={routingURL(collection,row)} aria-label={`路由 ${row.name}`} title="路由规则"><Icon name="route" size={14}/></a>{/if}{#if canViewDetails}<button class="icon-button" aria-label={`查看 ${row.name}`} title="查看详情" onclick={()=>show(row)}><Icon name="eye" size={14}/></button>{/if}{#if canManage(row)}<button class="icon-button" aria-label={`编辑 ${row.name}`} title="编辑服务器" onclick={()=>create(row)}><Icon name="edit" size={14}/></button>{/if}{#if config.action&&canAct(row)}<button class="icon-button" aria-label={`${config.action} ${row.name}`} title={config.action} disabled={acting} onclick={()=>action(row)}><Icon name="refresh" size={14}/></button>{/if}{#if canDelete(row)}<button class="icon-button" aria-label={`删除服务器 ${row.name}`} title="删除服务器" disabled={saving} onclick={()=>requestDelete(row)}><Icon name="trash" size={14}/></button>{/if}{/snippet}</ServerManagementCard>{:else}<div class="empty"><Icon name="search" size={28}/><h3>没有匹配的服务器</h3><p>试试其他关键词或状态。</p></div>{/each}</div>{/if}<div class="table-scroll" class:inactive-view={collection==='servers'&&serverView!=='list'} inert={collection==='servers'&&serverView!=='list'} aria-hidden={collection==='servers'&&serverView!=='list'}>{#if collection==='servers'}<table class="server-management-table" aria-label="服务器列表"><colgroup><col class="name-col"/><col class="connection-col"/><col class="address-col"/><col class="speed-col"/><col class="traffic-col"/><col class="services-col"/><col class="actions-col"/></colgroup><thead><tr><th scope="col">名称</th><th scope="col">连接模式</th><th scope="col">IP 地址</th><th scope="col">网速</th><th scope="col">流量</th><th scope="col">服务</th><th scope="col" class="actions-heading">操作</th></tr></thead><tbody>{#each visible as row (row.id)}<ServerManagementRow server={row} {hideIP} onconnection={canManage(row)?mode=>changeServerConnection(row,mode):undefined} onview={canViewDetails?()=>show(row):undefined} onconfig={canManage(row)&&canViewDetails?()=>xrayServer=row:undefined} onagent={canManage(row)&&canViewDetails?()=>show(row,'接入指引'):undefined}>{#snippet actions()}{#if demo.user?.role==='admin'&&routingURL(collection,row)}<a class="icon-button" href={routingURL(collection,row)} aria-label={`路由 ${row.name}`} title="路由规则"><Icon name="route" size={14}/></a>{/if}{#if canViewDetails}<button class="icon-button" aria-label={`查看 ${row.name}`} title="查看详情" onclick={()=>show(row)}><Icon name="search" size={14}/></button>{/if}{#if canManage(row)}<button class="icon-button" aria-label={`编辑 ${row.name}`} title="编辑服务器" onclick={()=>create(row)}><Icon name="edit" size={14}/></button>{/if}{#if config.action&&canAct(row)}<button class="icon-button" aria-label={`${config.action} ${row.name}`} title={config.action} disabled={acting} onclick={()=>action(row)}><Icon name="refresh" size={14}/></button>{/if}{#if canDelete(row)}<button class="icon-button delete-server" aria-label={`删除服务器 ${row.name}`} title="删除服务器" disabled={saving} onclick={()=>requestDelete(row)}><Icon name="x" size={14}/></button>{/if}{/snippet}</ServerManagementRow>{:else}<tr><td colspan="7"><div class="empty"><Icon name="search" size={28}/><h3>没有匹配的服务器</h3><p>试试其他关键词或状态。</p></div></td></tr>{/each}</tbody></table>{:else}<table><thead><tr>{#each config.columns as [,label]}<th>{label}</th>{/each}<th>操作</th></tr></thead><tbody>{#each visible as row}<tr>{#each config.columns as [key],i}<td>{#if i===0}{#if canViewDetails}<button class="identity" onclick={()=>show(row)}>{@render rowIdentity(row,key)}</button>{:else}<div class="identity">{@render rowIdentity(row,key)}</div>{/if}{:else if collection==='tasks'&&key==='target'}{#if taskView(row).serverURL}<a class="quiet-link" href={taskView(row).serverURL}>{taskView(row).targetName}</a>{:else}<strong>{taskView(row).targetName}</strong>{/if}<small class="muted task-target-address">{taskView(row).address||taskView(row).targetId}</small>{:else if key==='status'||key==='result'}<Badge value={collection==='tasks'?taskView(row).status:row[key]??'—'}/>{#if collection==='tasks'&&taskView(row).message}<small class="muted task-wait-hint">{taskView(row).message}</small>{/if}{:else if collection==='nodes'&&key==='latency'}<span class:muted={['queued','running','cancelled'].includes(nodeTests.state.results[row.id]?.status??'')} class:error={nodeResultsSynced?row.latencyStatus==='failed':nodeTests.state.results[row.id]?.status==='failed'} title={nodeLatencyHint(row)}>{nodeLatency(row)}</span>{:else if key==='cost'||key==='amount'}{money(Number(row[key]??0))}{:else if collection==='servers'&&key==='address'&&hideIP}•••.•••.•••.•••{:else}{formatDisplayValue(row[key])}{/if}</td>{/each}<td><div class="row-actions">{#if demo.user?.role==='admin'&&['servers','inbounds','nodes'].includes(collection)&&routingURL(collection,row)}<a class="icon-button" href={routingURL(collection,row)} aria-label={`路由 ${row.name}`} title="路由规则"><Icon name="route" size={14}/></a>{/if}{#if collection==='nodes'&&canAct(row)}<button class="button small" aria-label={`测速 ${row.name}`} title="测试 TCP 连接延迟" disabled={nodeTests.state.running||acting} onclick={()=>testNodes([row])}><Icon name="zap" size={14}/>{nodeTests.state.results[row.id]?.status==='running'?'测速中…':'测速'}</button>{/if}{#if canViewDetails}<button class="icon-button" aria-label={`查看 ${row.name}`} onclick={()=>show(row)}><Icon name="eye"/></button>{/if}{#if canManage(row)}<button class="icon-button" aria-label={`编辑 ${row.name}`} onclick={()=>create(row)}><Icon name="edit"/></button>{/if}{#if collection!=='nodes'&&config.action&&canAct(row)}<button class="icon-button" aria-label={`${config.action} ${row.name}`} onclick={()=>action(row)}><Icon name={collection==='billing'?'check':'refresh'}/></button>{/if}{#if collection==='servers'&&canDelete(row)}<button class="button small danger" aria-label={`删除服务器 ${row.name}`} disabled={saving} onclick={()=>requestDelete(row)}><Icon name="trash" size={14}/>删除</button>{/if}{#if logCollection&&demo.user?.role==='admin'}<button class="button small danger" aria-label={`删除记录 ${row.name}`} title={canDelete(row)?'删除这条历史记录':row.deleteReason??'任务尚未结束、结果未明或仍被使用，暂不能删除'} disabled={saving||!canDelete(row)} onclick={()=>requestDelete(row)}><Icon name="trash" size={14}/>删除</button>{/if}</div></td></tr>{:else}<tr><td colspan={config.columns.length+1}><div class="empty"><Icon name="search" size={28}/><h3>{collection==='nodes'&&demo.user?.role==='user'&&!rows.length?'暂无可用订阅节点':'这里还没有记录'}</h3><p>{collection==='nodes'&&demo.user?.role==='user'?rows.length?'试试其他关键词或状态。':'请在订阅管理中查看套餐状态，或联系管理员分配节点。':canCreate?'试试其他关键词，或创建一条记录。':'试试其他关键词。'}</p></div></td></tr>{/each}</tbody></table>{/if}</div></div><div class="table-footer"><span>显示 {filtered.length?offset+1:0}–{Math.min(offset+10,filtered.length)} / {filtered.length}</span><div class="actions"><button class="button small" disabled={offset===0} onclick={()=>offset-=10}>上一页</button><button class="button small" disabled={offset+10>=filtered.length} onclick={()=>offset+=10}>下一页</button></div></div></section>
{#if collection==='outbounds'}<p class="hint space-top">端口转发请在<a href="/extensions">扩展能力</a>的“转发与隧道”中设置。</p>{/if}
{#if collection==='nodes'}<p class="hint space-top">测速显示主控到节点的 TCP 连接延迟；全部测速覆盖所有分页中可测速的节点。{demo.user?.role==='admin'?'只接入 VLESS TCP REALITY，旧的不兼容节点保留供编辑、停用或删除。':'订阅变更后，可用节点会随之更新。'}</p>{/if}
{#if collection==='sources'}<p class="hint space-top">仅同步 VLESS TCP REALITY 节点，其他协议或传输会显示为不支持。上游额度仅用于展示来源用量；成员实际用量由自建入口独立统计。</p>{/if}
{#if xrayServer&&collection==='servers'&&demo.user?.role==='admin'}{#key xrayServer.id}<XrayManager server={xrayServer} initialSection={page.url.searchParams.get('tab')==='inbounds'?'inbounds':page.url.searchParams.get('tab')==='outbounds'?'outbounds':page.url.searchParams.get('tab')==='routing'?'routing':'config'} routingScope={page.url.searchParams.get('routingScope')??''} initialInbound={page.url.searchParams.get('inbound')??''} onclose={()=>xrayServer=null}/>{/key}{/if}
{#if onboardingOpen}<ServerOnboarding bind:open={onboardingOpen}/>{/if}
{#if collection==='servers'&&demo.user?.role==='admin'}<Modal bind:open={sharingOpen} title="服务器管理分享" description="接入共享服务器或管理已有授权" wide>{#if sharingOpen}<FederationAgent/>{/if}</Modal>{/if}
<Modal bind:open={edit} title={`${isNew?'新增':'编辑'} · ${config.title}`} description="保存到主控；配置下发与执行结果单独记录" wide>{#if collection==='nodes'&&!isNew&&!isSupportedNode(form)}<p class="hint">此节点的协议或配置不受支持。可替换完整节点链接后保存，或停用此记录。</p>{/if}{#if collection==='servers'&&form.xray_mode&&form.xray_mode!=='embedded'}<p class="hint">此记录使用已移除的外部模式。保存后请使用新的内嵌 Agent 重新接入；原有服务需手动维护。</p>{/if}<form onsubmit={e=>{e.preventDefault();submit();}}><div class="form-grid">{#each formFields as field}<label class:full={field.type==='textarea'||['json','jsonarray'].includes(field.type??'')} class="field"><span>{field.label}{field.required?' *':''}</span>{#if field.hint}<small class="hint">{field.hint}</small>{/if}{#if field.type==='fixed'}<input value={form[field.key]??field.value} readonly/>{:else if field.type==='select'||['servers','plans','members','carpools','endpoints'].includes(field.type??'')}<AppSelect aria-label={field.label} bind:value={form[field.key]} options={fieldOptions(field)} required={field.required} onchange={collection==='outbounds'&&field.key==='protocol'?changeOutboundType:undefined}/>{:else if field.type==='checkbox'}<input type="checkbox" bind:checked={form[field.key]}/>{:else if field.type==='serverIds'}<div class="stack">{#each demo.data.servers as server}<label class="tag"><input type="checkbox" bind:group={form[field.key]} value={server.id}/>{server.name}</label>{/each}</div>{:else if field.type==='textarea'||['json','jsonarray'].includes(field.type??'')}<textarea rows={['json','jsonarray'].includes(field.type??'')?6:3} class:code-editor={['json','jsonarray'].includes(field.type??'')} spellcheck={field.type!=='json'} bind:value={form[field.key]}></textarea>{:else if field.type==='number'}<input type="number" min={field.min??0} max={field.max} step="any" bind:value={form[field.key]}/>{:else}<input type={field.type??'text'} bind:value={form[field.key]} required={field.required} placeholder={field.placeholder}/>{/if}</label>{/each}</div>{#if collection==='members'}<BehaviorEditor bind:value={form.behaviorLimits}/><NodeLimitEditor bind:row={form}/>{/if}{#if collection==='inbounds'}<ManagedProtocolFields bind:form server={demo.data.servers.find(s=>s.id===form.serverId||s.name===form.server)} bind:busy={keyBusy}/>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button type="button" class="button" onclick={()=>edit=false}>取消</button><button class="button primary" type="submit" disabled={saving||keyBusy}>{saving?'保存中…':'保存'}</button></div></form></Modal>
<Modal bind:open={detail} title={selected?.name??'详情'} description={`${config.title} · 记录详情`} wide>{#if selected&&canViewDetails}{#key selected.id}<div class="tabs">{#each ['概况',...(collection==='servers'?['资源与配置','接入指引']:collection==='inbounds'?['客户端']:collection==='tasks'?['执行步骤','执行结果']:collection==='billing'?['核销确认']:collection==='notifications'?['消息预览']:[])] as tab}<button class:active={detailTab===tab} onclick={()=>{detailTab=tab;if(tab==='接入指引'&&!enrollment)loadEnrollment();if(tab==='执行结果')readTaskOutput();}}>{tab}</button>{/each}</div>
{#if collection==='tasks'&&taskView(selected).message}<div class="status-banner space-top"><div><strong>目标：{taskView(selected).targetName}{taskView(selected).address?' · '+taskView(selected).address:''}</strong><p>{taskView(selected).message}</p>{#if taskView(selected).serverURL}<a class="quiet-link" href={taskView(selected).serverURL} onclick={()=>detail=false}>查看服务器与接入配置</a>{/if}</div></div>{/if}
{#if detailTab==='客户端'}<div class="stack">{#each demo.data.subscriptions.filter(s=>s.status!=='停用') as sub}<div class="car-summary"><div><strong>{sub.member}</strong><small>{formatNumber(sub.used)} / {formatNumber(sub.limit)} GB · {sub.expires}</small></div><a class="button small" href="/subscriptions" onclick={()=>detail=false}>管理凭据</a></div>{/each}</div><p class="hint">套餐实例与入站的实际关联以主控记录为准。</p>
{:else if detailTab==='资源与配置'}<div class="metric-list"><div><small>CPU</small><strong>{formatUsagePercent(selected.cpu)}</strong></div><div><small>内存</small><strong>{formatUsagePercent(selected.memory)}</strong></div><div><small>核心版本</small><strong>{selected.core??'尚未上报'}</strong></div></div><p class="hint">保存配置不代表节点已经应用；请以 Agent 回报和任务结果为准。</p><div class="actions space-top">{#each [['core.start','启动核心'],['core.stop','停止核心'],['core.restart','重启核心']] as [operation,label]}<button class="button" disabled={acting} onclick={async()=>{acting=true;try{await runAction(operation,selected!.id,'servers');toast('请求已受理，请查看执行状态');}catch(cause){toast(errorMessage(cause));}finally{acting=false;}}}>{label}</button>{/each}</div>
<div class="space-top"><div class="section-head"><h3>完整核心配置</h3><button class="button small" disabled={acting} onclick={readCoreConfig}>从 Agent 读取</button></div><p class="hint">此处直接读取或应用 Agent 的完整配置，包含连接凭据。应用会重启核心；后续从入站页面发布会重新生成配置。</p><label class="field space-top">Xray JSON<textarea class="code-editor" aria-label="完整 Xray 配置" bind:value={coreConfig} placeholder="从 Agent 读取，或粘贴完整配置" spellcheck="false"></textarea></label>{#if coreError}<p class="error" role="alert">{coreError}</p>{/if}{#if configTask}<p class="hint">任务：{configTask} · <a href={`/tasks?detail=${encodeURIComponent(configTask)}`}>查看执行结果</a></p>{/if}<div class="actions"><button class="button primary" disabled={acting||!coreConfig.trim()} onclick={applyCoreConfig}>{acting?'处理中…':'应用配置并重启核心'}</button></div></div>
{:else if detailTab==='接入指引'}<AgentInstall {enrollment} busy={acting} onrefresh={loadEnrollment}/>
{:else if detailTab==='执行结果'}<div class="section-head"><Badge value={taskView(selected).status}/><button class="button small" disabled={loading} onclick={readTaskOutput}>刷新结果</button></div>{#if selected.error}<p class="error space-top" role="alert">{selected.error}</p>{/if}{#if taskOutputError}<p class="error space-top" role="alert">{taskOutputError}</p>{/if}<div class="space-top">{#if loading}<p class="hint" role="status">正在读取执行结果…</p>{:else if taskOutput}<ExpandableValue value={taskOutput} label="执行结果详情" force />{:else}<p class="hint">{taskView(selected).pending?'任务尚未下发，无执行结果':taskView(selected).retired?'任务未执行':'尚未收到 Agent 执行结果'}</p>{/if}</div><p class="hint">此结果通过授权详情读取，可能包含配置凭据。</p>{:else if detailTab==='执行步骤'}<div class="job-steps">{#each (selected.steps??'执行结果').split(',') as step,i}<div class="job-step"><span class="soft-icon"><Icon name={selected.status==='成功'?'check':'clock'}/></span><div><strong>{i+1}. {step}</strong><p class="muted">{selected.status==='成功'?'执行成功':selected.status??'等待处理'}</p></div></div>{/each}</div>
{:else if detailTab==='核销确认'}<p class="hint">历史账单演示已停用。套餐分配与续期通过套餐实例管理。</p>
{:else if detailTab==='消息预览'}<div class="notification-preview"><strong>ASWired · {selected.name}</strong><p>{selected.message??selected.trigger}</p><small>接收者：{selected.target} · {selected.channel}</small></div><button class="button space-top" disabled={acting} onclick={()=>action(selected!)}>测试通知</button>
{:else}<div class="detail-grid">{#each Object.entries(selected).filter(([key])=>!(collection==='servers'&&key==='xray_mode')&&!['id','token','uri','steps','privateKey','realitySettings','canManage','canTest','subscriptionAuthorized','canDelete','deleteReason'].includes(key)) as [key,value] (key)}<div><small>{config.fields.find(f=>f.key===key)?.label??config.columns.find(c=>c[0]===key)?.[1]??realityLabels[key]??detailLabels[key]??key}</small><ExpandableValue value={collection==='servers'&&['cpu','memory'].includes(key)?formatUsagePercent(value):value}/></div>{/each}</div>{/if}
<div class="modal-actions">{#if demo.user?.role==='admin'&&['servers','inbounds','nodes'].includes(collection)&&routingURL(collection,selected)}<a class="button" href={routingURL(collection,selected)} onclick={()=>detail=false}>路由规则</a>{/if}{#if collection==='nodes'}<a class="button" href={`/temporary-subscriptions?node=${encodeURIComponent(selected.id)}`} onclick={()=>detail=false}>创建临时订阅</a>{/if}{#if canDelete(selected)}<button class="button danger" disabled={saving} onclick={()=>requestDelete(selected!)}>{collection==='servers'?'删除服务器':'删除记录'}</button>{/if}{#if canManage(selected)}<button class="button" onclick={()=>{detail=false;create(selected!);}}>编辑</button>{/if}{#if collection==='certificates'}<button class="button" disabled={acting} onclick={()=>{certificatePEM='';certificateKey='';certificateOpen=true;}}>上传证书</button><button class="button" disabled={acting} onclick={()=>certificateAction('certificate.deploy')}>部署证书</button>{/if}{#if config.action&&detailTab==='概况'&&canAct(selected)}<button class="button primary" disabled={acting||nodeTests.state.running} onclick={()=>collection==='nodes'?testNodes([selected!]):action(selected!)}>{collection==='nodes'?'测速':config.action}</button>{/if}<button class="button" onclick={()=>detail=false}>关闭</button></div>{/key}{/if}</Modal>
<Modal bind:open={deleting} title={collection==='servers'?'删除服务器':'删除记录'} description={`确认删除「${selected?.name??''}」？${logCollection?'删除后无法恢复。':'此操作会从主控删除这条记录。'}`}>{#if collection==='servers'}<p class="hint">删除后将撤销该服务器的接入凭据，服务器上的 Agent 程序和代理核心会继续保留。有关联入站、出站或订阅时，请先处理关联记录。</p>{/if}{#if logCollection}<p class="hint">{collection==='tasks'?'删除这条任务的执行记录和结果。已应用到服务器的配置会继续生效。':'删除这条审计记录。对应操作及其结果不会撤销。'}</p>{/if}{#if deleteError}<p class="error" role="alert">{deleteError}</p>{/if}<div class="modal-actions"><button class="button" disabled={saving} onclick={()=>deleting=false}>取消</button><button class="button danger" disabled={saving} onclick={deleteSelected}>{saving?'删除中…':'确认删除'}</button></div></Modal>

<Modal bind:open={certificateOpen} title="上传证书材料" description="上传相互匹配的 PEM 证书链和私钥，主控验证域名、有效期与密钥后保存。" wide><label class="field">证书链 PEM<textarea class="code-editor short" bind:value={certificatePEM}></textarea></label><label class="field space-top">私钥 PEM<textarea class="code-editor short" bind:value={certificateKey}></textarea></label><div class="modal-actions"><button class="button" onclick={()=>certificateOpen=false}>取消</button><button class="button primary" disabled={acting||!certificatePEM||!certificateKey} onclick={()=>certificateAction('certificate.upload')}>验证并保存</button></div></Modal>

<style>
 .server-management-table{width:100%;min-width:1160px;table-layout:fixed;border-collapse:collapse}.server-management-table .name-col{width:25%}.server-management-table .connection-col{width:10%}.server-management-table .address-col{width:14%}.server-management-table .speed-col{width:9%}.server-management-table .traffic-col{width:17%}.server-management-table .services-col{width:13%}.server-management-table .actions-col{width:216px}.server-management-table th{height:45px;padding:10px 14px;text-align:left;font-size:11px;font-weight:600;background:var(--nested);color:var(--muted);border-bottom:1px solid var(--line)}.server-management-table th.actions-heading{text-align:right}.server-view-body{min-width:0}.server-view-body>.table-scroll{min-width:0;max-width:100%;overflow-x:auto;border-radius:6px!important}.server-view-body>.inactive-view{height:0;overflow:hidden}.server-collection{min-width:0}.server-management-table :global(td){letter-spacing:0}
 .server-tools{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:18px}.server-tools>.actions{gap:8px;flex-wrap:wrap}.server-tools :global(.button){font-size:12px}.server-counts{display:flex;align-items:center;gap:14px;color:var(--muted);font-size:12px}.server-counts>span{display:flex;align-items:center;gap:7px;white-space:nowrap}.server-counts strong{color:var(--foreground);font-variant-numeric:tabular-nums}.server-counts i{width:6px;height:6px;border-radius:50%;background:var(--muted)}.server-counts i.online{background:var(--success)}
 .server-card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,340px),1fr));gap:18px;padding:4px 16px 20px;align-items:stretch}.server-card-grid>:global(article){width:100%;height:100%}.server-card-grid>.empty{grid-column:1/-1}.server-collection{background:transparent;border-color:transparent}.server-collection>.toolbar{padding:0 0 20px!important;min-height:62px}.server-collection>.table-footer{padding-left:0;padding-right:0}.server-view-body{display:grid;min-height:450px;padding-bottom:20px}.server-view-body>div{grid-area:1/1;align-self:start}.inactive-view{visibility:hidden;pointer-events:none}.server-view-body>.server-card-grid{padding:0}.server-view-body>.table-scroll{border:1px solid var(--line);border-radius:12px;background:var(--card)}.server-tools .view-switch button{min-width:62px;justify-content:center}.server-collection>.toolbar>.actions>.muted{min-width:65px;text-align:right;font-variant-numeric:tabular-nums}.view-switch button{display:flex;align-items:center;gap:6px}.toolbar>.actions{flex-wrap:wrap}


 .log-retention{margin-bottom:1rem;}
 .detail-grid{grid-template-columns:repeat(2,minmax(0,1fr));}
 .detail-grid>div{min-width:0;}
 @media(max-width:767px){.detail-grid{grid-template-columns:1fr;}}
 .node-test-progress{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap;margin-bottom:1rem;color:var(--muted);}
 .task-target-address{display:block;margin-top:.25rem;}
 .task-wait-hint{display:block;max-width:24rem;margin-top:.4rem;white-space:normal;line-height:1.5;}
</style>
